import re

from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone


class Eidutil(GenericUnixCommand):
    """Eidutil command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Eidutil command lists information about given container.

        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        :param connection: moler connection to device, terminal when command is executed.
        :param options: is equal '' because it does not have any options
        """
        super(Eidutil, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.current_ret["RESULT"] = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "eidutil"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Summary line.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_headers(line)
            except ParsingDone:
                pass
        return super(Eidutil, self).on_new_line(line, is_full_line)

    # RF1 Capability                 = 07 00 00 03 21 22 81 00
    _re_headers_and_values = re.compile(r"^(?P<HEADER>\w+\s\w+\s\w+|\w+\s\w+|\w+)\s+=\s(?P<VALUE>.+)")

    def _parse_headers(self, line):
        if self._regex_helper.search_compiled(Eidutil._re_headers_and_values, line):
            self.current_ret["RESULT"][self._regex_helper.group("HEADER")] = self._regex_helper.group("VALUE")

            raise ParsingDone


